import static com.consense.service.drafting.DraftNativeStoryEditorCandidateTest.*;

/** Source Word fidelity checks; rendering and actual whitespace readability require separate evidence. */
class DraftNativeLatinFontHintCandidateTest {
    private static final String ACTION="normalize_verified_latin_font_hint";
    private static final String HINT="<w:rPr><w:rFonts w:ascii=\"Times New Roman\" w:hAnsi=\"Times New Roman\" w:eastAsia=\"Adobe Heiti Std R\" w:hint=\"eastAsia\"/><w:b/><w:sz w:val=\"24\"/><w:lang w:val=\"en-GB\" w:eastAsia=\"zh-CN\"/></w:rPr>";
    private static final String PROPS="<w:pPr><w:ind w:left=\"1985\" w:hanging=\"1061\" w:right=\"170\" w:rightChars=\"71\"/><w:jc w:val=\"both\"/></w:pPr>";
    private static String run(String text){return "<w:r>"+HINT+"<w:t xml:space=\"preserve\">"+text+"</w:t></w:r>";}
    private static Case source(String runs)throws Exception{return new Case(p("Before")+"<w:p>"+PROPS+runs+"</w:p>"+p("After")+"<w:sectPr/>");}
    private static final class Case {
        final byte[] bytes;final TemplateIndex index;final Map<String,byte[]> parts;
        Case(String body)throws Exception{Fixture fixture=new Fixture(body,"",Collections.emptyMap(),"");bytes=fixture.bytes;index=EDITOR.inspect(bytes);parts=unzip(bytes);}
        NativeLayoutPlan plan()throws Exception{return hints(new NativeLayoutPlan(index.getSourceSha256(),"synthetic-source-bound-hint",Collections.emptyList(),Collections.emptyList()),Collections.singletonList(index.anchor(index.mainParagraph(2).getId())));}
        DocxEditResult apply(List<Edit> edits)throws Exception{return EDITOR.applyWithParagraphBookmarks(bytes,new SourceEditBatch(index.getSourceSha256(),edits),Collections.emptyMap(),false,plan());}
    }
    private static NativeLayoutPlan hints(NativeLayoutPlan plan,List<NodeAnchor> targets)throws Exception{
        // Reflection lets the unchanged-source RED compile and fail on behavior, rather than missing symbols.
        Method method=NativeLayoutPlan.class.getMethod("withLatinFontHintParagraphs",List.class);return (NativeLayoutPlan)method.invoke(plan,targets);
    }
    private static List<NativeLayoutChange> changes(DocxEditResult result){List<NativeLayoutChange> out=new ArrayList<>();for(NativeLayoutChange c:result.getNativeLayoutLedger())if(ACTION.equals(c.getAction()))out.add(c);return out;}
    private static Element paragraph(DocxEditResult result,NativeLayoutChange action)throws Exception{Paragraph p=result.getIndex().paragraph(action.getGeneratedId());return elements(parse(unzip(result.getDocxBytes()).get(MAIN)),W,"p").get(p.getOrdinal()-1);}
    private static int hintCount(Element p){int count=0;NodeList fonts=p.getElementsByTagNameNS(W,"rFonts");for(int i=0;i<fonts.getLength();i++)if("eastAsia".equals(((Element)fonts.item(i)).getAttributeNS(W,"hint")))count++;return count;}
    private static String runText(Element run){StringBuilder text=new StringBuilder();NodeList nodes=run.getElementsByTagNameNS(W,"t");for(int i=0;i<nodes.getLength();i++)text.append(nodes.item(i).getTextContent());return text.toString();}
    private static int textRunHintCount(Element paragraph,boolean nonempty){int count=0;NodeList runs=paragraph.getElementsByTagNameNS(W,"r");for(int i=0;i<runs.getLength();i++){Element run=(Element)runs.item(i);if(runText(run).isEmpty()==nonempty)continue;NodeList fonts=run.getElementsByTagNameNS(W,"rFonts");for(int j=0;j<fonts.getLength();j++)if("eastAsia".equals(((Element)fonts.item(j)).getAttributeNS(W,"hint")))count++;}return count;}
    private static void undoHints(Element before,Element after,String marker){
        List<Element> remove=new ArrayList<>();String markerId=null;NodeList starts=after.getElementsByTagNameNS(W,"bookmarkStart");for(int i=0;i<starts.getLength();i++){Element s=(Element)starts.item(i);if(marker.equals(s.getAttributeNS(W,"name"))){markerId=s.getAttributeNS(W,"id");remove.add(s);}}
        assertNotNull(markerId);NodeList ends=after.getElementsByTagNameNS(W,"bookmarkEnd");for(int i=0;i<ends.getLength();i++){Element e=(Element)ends.item(i);if(markerId.equals(e.getAttributeNS(W,"id")))remove.add(e);}assertEquals(2,remove.size());for(Element e:remove)e.getParentNode().removeChild(e);
        NodeList originalRuns=before.getElementsByTagNameNS(W,"r"),currentRuns=after.getElementsByTagNameNS(W,"r");assertEquals(originalRuns.getLength(),currentRuns.getLength());
        for(int i=0;i<originalRuns.getLength();i++){Element originalRun=(Element)originalRuns.item(i),currentRun=(Element)currentRuns.item(i);NodeList original=originalRun.getElementsByTagNameNS(W,"rFonts"),current=currentRun.getElementsByTagNameNS(W,"rFonts");assertEquals(original.getLength(),current.getLength());
            if(runText(originalRun).isEmpty()){assertEquals(shape(originalRun),shape(currentRun),"Empty-text runs including tab fonts must remain exact");continue;}
            for(int j=0;j<original.getLength();j++)if("eastAsia".equals(((Element)original.item(j)).getAttributeNS(W,"hint"))){assertFalse(((Element)current.item(j)).hasAttributeNS(W,"hint"));((Element)current.item(j)).setAttributeNS(W,"w:hint","eastAsia");}
        }
        assertEquals(shape(before),shape(after),"Every space, run boundary, font name/size, rPr/pPr, marker and native control must survive reversal");
    }
    private static String shape(Node node){StringBuilder out=new StringBuilder();shape(node,out);return out.toString();}
    private static void shape(Node n,StringBuilder out){if(n instanceof Element){out.append('<').append(n.getNamespaceURI()).append('|').append(n.getLocalName());Map<String,String> attrs=new TreeMap<>();NamedNodeMap raw=n.getAttributes();for(int i=0;i<raw.getLength();i++){Node a=raw.item(i);if(!"http://www.w3.org/2000/xmlns/".equals(a.getNamespaceURI()))attrs.put("{"+a.getNamespaceURI()+"}"+a.getLocalName(),a.getNodeValue());}out.append(attrs).append('>');for(Node c=n.getFirstChild();c!=null;c=c.getNextSibling())shape(c,out);out.append("</>");}else if(n.getNodeType()==Node.TEXT_NODE||n.getNodeType()==Node.CDATA_SECTION_NODE)out.append(n.getNodeValue());}

    @Test void actualRegisteredFullSctLatinFamilyChangesOnly1067HintsAndKeepsSourceSpacesAndRuns()throws Exception{
        String dir=System.getProperty("consense.acceptance.sourceDir");assumeTrue(dir!=null,"Explicit original 2a directory required");byte[] bytes=Files.readAllBytes(Paths.get(dir,"02_Special Conditions of Tender (SCT).docx"));TemplateIndex index=EDITOR.inspect(bytes);assertEquals("7def01d62e07b35dd86beeff995e0e37d73ce18adca2746e2a6f6d9bafb5aaa4",index.getSourceSha256());
        Map<String,Object> expected=JsonUtils.mapper().readValue(getClass().getResourceAsStream("/drafting/sct-row-latin-source-family.json"),Map.class);List<Object> targets=DraftBusinessRules.list(expected.get("latinFontHintParagraphs"));assertEquals(150,targets.size());
        Map<String,Object> registry=JsonUtils.mapper().readValue(getClass().getResourceAsStream("/drafting/libreoffice-native-layout.json"),Map.class);Map<String,Object> registered=DraftBusinessRules.list(registry.get("sources")).stream().map(DraftBusinessRules::asMap).filter(r->index.getSourceSha256().equals(r.get("sourceSha256"))).findFirst().orElseThrow(AssertionError::new);assertEquals(targets,registered.get("latinFontHintParagraphs"));assertNotNull(DraftNativeLayout.plan(index,"SCT","libreoffice"));
        List<NodeAnchor> anchors=new ArrayList<>();for(Object raw:targets){Map<String,Object> target=DraftBusinessRules.asMap(raw);NodeAnchor anchor=index.anchor(String.valueOf(target.get("paragraphId")));assertEquals(target.get("paragraphSha256"),anchor.getSha256());anchors.add(anchor);}
        NativeLayoutPlan plan=hints(new NativeLayoutPlan(index.getSourceSha256(),"source-family-hints-isolated",Collections.emptyList(),Collections.emptyList()),anchors);DocxEditResult result=EDITOR.applyWithParagraphBookmarks(bytes,new SourceEditBatch(index.getSourceSha256(),Collections.emptyList()),Collections.emptyMap(),false,plan);
        List<NativeLayoutChange> actual=changes(result);assertEquals(150,actual.size(),"COMPLETE_SOURCE_BOUND_LATIN_HINT_FAMILY_REQUIRED");Document beforeDocument=parse(unzip(bytes).get(MAIN)),afterDocument=parse(unzip(result.getDocxBytes()).get(MAIN));List<Element> before=elements(beforeDocument,W,"p"),savedParagraphs=elements(afterDocument,W,"p");assertEquals(before.size(),savedParagraphs.size());Set<String> expectedIds=new HashSet<>();int total=0,retainedEmpty=0;
        for(Object raw:targets){Map<String,Object> target=DraftBusinessRules.asMap(raw);int ordinal=((Number)target.get("sourceParagraphOrdinal")).intValue();Paragraph source=index.mainParagraph(ordinal);expectedIds.add(source.getId());NativeLayoutChange change=actual.stream().filter(a->source.getId().equals(a.getSource().getId())).findFirst().orElseThrow(AssertionError::new);assertEquals(source.getSha256(),change.getSource().getSha256());assertEquals("APPLIED",change.getStatus());assertEquals(ordinal,result.getIndex().paragraph(change.getGeneratedId()).getOrdinal());Element after=savedParagraphs.get(ordinal-1);int eligible=textRunHintCount(before.get(ordinal-1),true),protectedEmpty=textRunHintCount(before.get(ordinal-1),false);total+=eligible;retainedEmpty+=protectedEmpty;assertEquals(0,textRunHintCount(after,true),"All eligible text-run hints removed at source paragraph"+ordinal);assertEquals(protectedEmpty,textRunHintCount(after,false),"All empty-text run hints retained at source paragraph"+ordinal);assertEquals(protectedEmpty,hintCount(after),"No other run hints remain at source paragraph"+ordinal);assertEquals(source.getText(),result.getIndex().paragraph(change.getGeneratedId()).getText(),"Every source space/tab is exact");undoHints(before.get(ordinal-1),after,change.getLayoutId());}
        assertEquals(1067,total);assertEquals(15,retainedEmpty);assertEquals(1082,total+retainedEmpty);String beforeShape=shape(beforeDocument.getDocumentElement()),afterShape=shape(afterDocument.getDocumentElement());assertFalse(beforeShape.isEmpty(),"Whole main XML observation must be nonempty");assertEquals(beforeShape,afterShape,"Entire main XML must reverse after all150 source paragraphs, including untouched empty tab runs");Set<String> actualIds=new HashSet<>();for(NativeLayoutChange change:actual)actualIds.add(change.getSource().getId());assertEquals(expectedIds,actualIds);unchanged(unzip(bytes),unzip(result.getDocxBytes()),Set.of(MAIN));assertEquals(index.getSourceSha256(),EDITOR.inspect(bytes).getSourceSha256());
    }
    @Test void safeLatinTypographyAccentsAndWhitespaceKeepExactSourceStyles()throws Exception{
        Case c=source(run("Latin caf\u00e9 \u201cquoted\u201d\u2014words\u00a0with\u202fspace\u2026"));DocxEditResult result=c.apply(Collections.emptyList());NativeLayoutChange action=changes(result).get(0);assertEquals("APPLIED",action.getStatus());Element before=elements(parse(c.parts.get(MAIN)),W,"p").get(1),after=paragraph(result,action);assertEquals(0,hintCount(after));assertEquals(c.index.mainParagraph(2).getText(),result.getIndex().mainParagraph(2).getText());undoHints(before,after,action.getLayoutId());unchanged(c.parts,unzip(result.getDocxBytes()),Set.of(MAIN));
    }
    @Test void hintedEmptyTextTabRunRetainsItsFontWhileEligibleLatinRunIsCleared()throws Exception{
        Case c=source(run("Latin source text")+"<w:r>"+HINT+"<w:tab/></w:r>");DocxEditResult result=c.apply(Collections.emptyList());NativeLayoutChange action=changes(result).get(0);assertEquals("APPLIED",action.getStatus());Element before=elements(parse(c.parts.get(MAIN)),W,"p").get(1),after=paragraph(result,action);assertEquals(2,hintCount(before));assertEquals(0,textRunHintCount(after,true));assertEquals(1,textRunHintCount(after,false));assertEquals(1,hintCount(after));assertEquals(c.index.mainParagraph(2).getText(),result.getIndex().mainParagraph(2).getText());assertTrue(result.getIndex().mainParagraph(2).hasNormalizedNativeLatinFontHints());undoHints(before,after,action.getLayoutId());unchanged(c.parts,unzip(result.getDocxBytes()),Set.of(MAIN));
    }
    @Test void printableAsciiIncludesPunctuationAndPureSpaceRunsButPreservesAllSourceStyleAndExactWhitespace()throws Exception{
        Case c=source(run("Latin words")+run(" ")+run(" ")+run("(4): punctuation.")+"<w:r><w:tab/></w:r>");DocxEditResult result=c.apply(Collections.emptyList());NativeLayoutChange action=changes(result).get(0);assertEquals("APPLIED",action.getStatus());Element before=elements(parse(c.parts.get(MAIN)),W,"p").get(1),after=paragraph(result,action);assertEquals(4,hintCount(before));assertEquals(0,hintCount(after));assertEquals("Latin words  (4): punctuation.\t",result.getIndex().mainParagraph(2).getText());undoHints(before,after,action.getLayoutId());unchanged(c.parts,unzip(result.getDocxBytes()),Set.of(MAIN));
    }
    @Test void adoptedTextChangesAndExplicitClearsAreSkippedWithoutOverwritingManualContent()throws Exception{
        Case c=source(run("Latin source text"));Paragraph p=c.index.mainParagraph(2);
        for(Edit edit:Arrays.asList(Edit.replaceSpan("adopted",p,0,p.getText().length(),p.getText(),"Adopted exact text"),Edit.clearParagraph("manual-clear",p))){DocxEditResult result=c.apply(Collections.singletonList(edit));NativeLayoutChange a=changes(result).get(0);assertEquals("SKIPPED_CHANGED",a.getStatus());assertNull(a.getLayoutId());assertEquals(edit.getType()==EditType.CLEAR_PARAGRAPH?"":"Adopted exact text",result.getIndex().mainParagraph(2).getText());assertTrue(result.getIndex().getFeatures().stream().noneMatch(f->f.getName()!=null&&f.getName().startsWith("CL")));}
    }
    @Test void removedTargetIsSkippedAndNewlyInsertedParagraphsNeverAcquireThisRepair()throws Exception{
        Case c=source(run("Latin source text"));Paragraph target=c.index.mainParagraph(2);DocxEditResult removed=c.apply(Collections.singletonList(Edit.deleteParagraph("remove",target)));assertEquals("SKIPPED_REMOVED",changes(removed).get(0).getStatus());assertNull(changes(removed).get(0).getGeneratedId());
        DocxEditResult inserted=c.apply(Collections.singletonList(Edit.insertParagraphs("insert",target,true,Collections.singletonList("New manually supplied text"),target)));assertEquals(1,changes(inserted).size());assertEquals("APPLIED",changes(inserted).get(0).getStatus());assertEquals("New manually supplied text",inserted.getIndex().mainParagraph(3).getText());assertEquals(1,hintCount(elements(parse(unzip(inserted.getDocxBytes()).get(MAIN)),W,"p").get(2)),"New source-unbound text keeps its original donor hint");
    }
    @Test void sourceAndNodeHashMismatchesStillRejectBeforeMutation()throws Exception{
        Case a=source(run("Latin source text")),b=source(run("Changed source text"));NativeLayoutPlan wrongSource=hints(new NativeLayoutPlan("wrong-source","synthetic",Collections.emptyList(),Collections.emptyList()),Collections.singletonList(a.index.anchor(a.index.mainParagraph(2).getId())));
        EditException source=assertThrows(EditException.class,()->EDITOR.applyWithParagraphBookmarks(a.bytes,new SourceEditBatch(a.index.getSourceSha256(),Collections.emptyList()),Collections.emptyMap(),false,wrongSource));assertEquals("LAYOUT_SOURCE_HASH_MISMATCH",source.getCode());
        NativeLayoutPlan stale=hints(new NativeLayoutPlan(a.index.getSourceSha256(),"synthetic",Collections.emptyList(),Collections.emptyList()),Collections.singletonList(b.index.anchor(b.index.mainParagraph(2).getId())));EditException node=assertThrows(EditException.class,()->EDITOR.applyWithParagraphBookmarks(a.bytes,new SourceEditBatch(a.index.getSourceSha256(),Collections.emptyList()),Collections.emptyMap(),false,stale));assertEquals("LAYOUT_ANCHOR_MISMATCH",node.getCode());assertEquals(a.index.getSourceSha256(),EDITOR.inspect(a.bytes).getSourceSha256());
    }
    @Test void mixedCjkGreekMathFieldRevisionAndOpaqueTextCannotEnterTheLatinRepair()throws Exception{
        for(String runs:Arrays.asList(run("Latin 中文"),run("Latin \u03a9"),run("Latin \u00d7 word"),run("Latin words")+PAGE,"<w:hyperlink>"+run("Latin words")+"</w:hyperlink>","<w:del>"+run("Latin words")+"</w:del>","<w:sdt><w:sdtContent>"+run("Latin words")+"</w:sdtContent></w:sdt>","<w:r>"+HINT+"<w:t>Latin words</w:t><w:tab/></w:r>")){
            Case c=source(runs);EditException failure=assertThrows(EditException.class,()->c.apply(Collections.emptyList()));assertEquals("LAYOUT_LATIN_HINT_SCOPE_CHANGED",failure.getCode());assertEquals(c.index.getSourceSha256(),EDITOR.inspect(c.bytes).getSourceSha256());
        }
    }
    @Test void ambiguousFontsDuplicateTargetsAndMissingEligibleHintsAreRejected()throws Exception{
        for(String runs:Arrays.asList("<w:r><w:rPr><w:rFonts w:hint=\"eastAsia\"/><w:rFonts w:hint=\"eastAsia\"/></w:rPr><w:t>Latin words</w:t></w:r>",run("123 (4) "),"<w:r><w:t>Latin without hint</w:t></w:r>")){Case c=source(runs);assertEquals("LAYOUT_LATIN_HINT_SCOPE_CHANGED",assertThrows(EditException.class,()->c.apply(Collections.emptyList())).getCode());}
        Case c=source(run("Latin words"));NodeAnchor p=c.index.anchor(c.index.mainParagraph(2).getId());NativeLayoutPlan duplicate=hints(new NativeLayoutPlan(c.index.getSourceSha256(),"synthetic",Collections.emptyList(),Collections.emptyList()),Arrays.asList(p,p));assertEquals("LAYOUT_LATIN_HINT_SCOPE_CHANGED",assertThrows(EditException.class,()->EDITOR.applyWithParagraphBookmarks(c.bytes,new SourceEditBatch(c.index.getSourceSha256(),Collections.emptyList()),Collections.emptyMap(),false,duplicate)).getCode());
    }
    @Test void persistedParagraphControlDetectsReintroducedHintsAndSurvivesNeighborEdits()throws Exception{
        Case c=source(run("Latin words"));DocxEditResult first=c.apply(Collections.emptyList());Map<String,Object> info=DraftNativeLayout.info("SCT","libreoffice",first);assertNotNull(info);String ledger=JsonUtils.write(Collections.singletonList(info));
        TemplateIndex current=first.getIndex();Paragraph before=current.mainParagraph(1);DocxEditResult shifted=EDITOR.apply(first.getDocxBytes(),new SourceEditBatch(current.getSourceSha256(),Collections.singletonList(Edit.insertParagraphs("neighbor",before,true,Collections.singletonList("New paragraph"),before))));Map<String,Object> kept=layout(DraftNativeLayout.bodyLedger(ledger,shifted));assertEquals("applied",kept.get("status"));
        Map<String,byte[]> parts=unzip(first.getDocxBytes());String xml=new String(parts.get(MAIN),StandardCharsets.UTF_8);assertTrue(xml.contains("w:rFonts"));xml=xml.replaceFirst("<w:rFonts ","<w:rFonts w:hint=\"eastAsia\" ");parts.put(MAIN,xml.getBytes(StandardCharsets.UTF_8));byte[] altered=zip(parts);TemplateIndex index=EDITOR.inspect(altered);DocxEditResult reread=EDITOR.apply(altered,new SourceEditBatch(index.getSourceSha256(),Collections.emptyList()));Map<String,Object> invalid=layout(DraftNativeLayout.bodyLedger(ledger,reread));assertEquals("unavailable",invalid.get("status"));assertEquals("CHANGED_LAYOUT_CONTROL",DraftBusinessRules.asMap(DraftBusinessRules.list(invalid.get("actions")).get(0)).get("status"));
    }
    private static Map<String,Object> layout(List<Object> rows){for(Object raw:rows){Map<String,Object> row=DraftBusinessRules.asMap(raw);if("native_layout".equals(row.get("kind")))return row;}throw new AssertionError("Native layout ledger missing");}
}
